import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

// Connection pool with SSL cert pinning (loaded at startup)
const caCert = readFileSync(process.env.PG_CA_CERT || '/etc/ssl/pg-ca.crt');
const pool = new Pool({
  host: process.env.PG_HOST,
  port: parseInt(process.env.PG_PORT || '5432'),
  database: process.env.PG_DATABASE || 'appdb',
  user: process.env.PG_USER,
  password: process.env.PG_PASSWORD,
  ssl: { ca: caCert, rejectUnauthorized: true },
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: verify HMAC signature on admin endpoints
function verifySignature(req, res, next) {
  const sig = req.headers['x-request-signature'];
  const ts = req.headers['x-request-timestamp'];
  if (!sig || !ts) return res.status(401).json({ error: 'Missing signature' });
  const age = Math.abs(Date.now() - parseInt(ts));
  if (age > 300000) return res.status(401).json({ error: 'Request expired' });
  const payload = `${req.method}:${req.path}:${ts}:${JSON.stringify(req.body)}`;
  const expected = crypto.createHmac('sha256', process.env.HMAC_SECRET || '')
    .update(payload).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(403).json({ error: 'Invalid signature' });
  }
  next();
}

// Public search endpoint - supports flexible filtering
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order, limit } = req.query;

    let query = 'SELECT id, name, description, price, category FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      // Category supports comma-separated values for multi-select
      const categories = category.split(',').map(c => c.trim());
      query += ` AND category IN (${categories.map(() => `$${paramIdx++}`).join(',')})`;
      params.push(...categories);
    }

    if (minPrice) {
      query += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }

    if (maxPrice) {
      query += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic sort - validated against allowed columns
    const allowedSort = ['price', 'name', 'created_at'];
    const sortColumn = allowedSort.includes(sortBy) ? sortBy : 'created_at';
    const sortOrder = order?.toUpperCase() === 'ASC' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortColumn} ${sortOrder}`;

    // Limit with cap
    const resultLimit = Math.min(parseInt(limit) || 25, 100);
    query += ` LIMIT ${resultLimit}`;

    const result = await pool.query(query, params);
    res.json({ products: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Admin reporting endpoint
app.post('/api/v2/admin/report', verifySignature, async (req, res) => {
  try {
    const { reportType, dateRange, groupBy } = req.body;

    const validReports = ['sales', 'inventory', 'returns'];
    if (!validReports.includes(reportType)) {
      return res.status(400).json({ error: 'Invalid report type' });
    }

    // Build report query with user-specified grouping
    let query = `SELECT ${groupBy}, COUNT(*) as total, SUM(amount) as revenue 
                 FROM ${reportType}_data 
                 WHERE created_at BETWEEN $1 AND $2 
                 GROUP BY ${groupBy}`;

    const result = await pool.query(query, [dateRange.start, dateRange.end]);
    res.json({ report: result.rows });
  } catch (err) {
    console.error('Report error:', err.message);
    res.status(500).json({ error: 'Report generation failed' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(3000, () => console.log('Product service listening on :3000'));
